#include "gui_forms/controls/object_view.hpp"

namespace gui_forms::detail::ic::object_view {

// ObjectView::icon_cell_size: finite(incoming.width) and finite(incoming.height) and incoming.width >= 86 and
// incoming.height >= 78 and incoming.width <= 512 and incoming.height <= 512; else failure invalid_argument.
[[nodiscard]] constexpr bool admits_icon_cell_size(const Size incoming) noexcept {
    const bool result = __builtin_isfinite(incoming.width)
                     && __builtin_isfinite(incoming.height)
                     && (incoming.width >= 86)
                     && (incoming.height >= 78)
                     && (incoming.width <= 512)
                     && (incoming.height <= 512);
    return result;
}

// ObjectView::details_row_height: finite(incoming) and incoming >= 20 and incoming <= 256; else failure
// invalid_argument.
[[nodiscard]] constexpr bool admits_details_row_height(const double incoming) noexcept {
    const bool result = __builtin_isfinite(incoming) && (incoming >= 20) && (incoming <= 256);
    return result;
}

} // namespace gui_forms::detail::ic::object_view
